




"use strict";

const Dependency = require("../Dependency");
const DependencyTemplate = require("../DependencyTemplate");








class ModuleDependency extends Dependency {
	




	constructor(request, sourceOrder) {
		super();
		
		this.request = request;
		
		this.userRequest = request;
		
		this.sourceOrder = sourceOrder;
		
		this.range = undefined;
		
		this._context = undefined;
		
		this.weak = false;
	}

	



	getContext() {
		return this._context;
	}

	



	getResourceIdentifier() {
		return `context${this._context || ""}|module${this.request}`;
	}

	



	couldAffectReferencingModule() {
		return true;
	}

	




	createIgnoredModule(context) {
		const RawModule = require("../RawModule");

		const module = new RawModule(
			"/* (ignored) */",
			`ignored|${context}|${this.request}`,
			`${this.request} (ignored)`
		);
		module.factoryMeta = { sideEffectFree: true };
		return module;
	}

	



	serialize(context) {
		const { write } = context;
		write(this.request);
		write(this.userRequest);
		write(this._context);
		write(this.range);
		write(this.sourceOrder);
		write(this.weak);
		super.serialize(context);
	}

	



	deserialize(context) {
		const { read } = context;
		this.request = read();
		this.userRequest = read();
		this._context = read();
		this.range = read();
		this.sourceOrder = read();
		this.weak = read();
		super.deserialize(context);
	}
}

ModuleDependency.Template = DependencyTemplate;

module.exports = ModuleDependency;
